use tonic::{transport::Server, Request, Response, Status};
use tokio::sync::RwLock;
use std::sync::Arc;
use std::collections::HashMap;

pub mod user_service {
    tonic::include_proto!("user_service");
}

use user_service::user_management_server::{UserManagement, UserManagementServer};
use user_service::{UpdateProfileRequest, UpdateProfileResponse, UserProfile};

#[derive(Debug, Clone)]
pub struct StoredUser {
    pub id: String,
    pub username: String,
    pub email: String,
    pub display_name: String,
    pub role: String,        // "user", "admin", "superadmin"
    pub is_verified: bool,
    pub credit_balance: i64,
    pub internal_flags: u32, // internal system flags
}

impl StoredUser {
    fn default_user(id: &str) -> Self {
        StoredUser {
            id: id.to_string(),
            username: String::new(),
            email: String::new(),
            display_name: String::new(),
            role: "user".to_string(),
            is_verified: false,
            credit_balance: 0,
            internal_flags: 0,
        }
    }
}

#[derive(Debug)]
pub struct UserService {
    db: Arc<RwLock<HashMap<String, StoredUser>>>,
}

// Field filtering configuration
#[derive(Debug, Clone)]
struct FieldPolicy {
    // Fields that can be updated by the user themselves
    user_mutable: Vec<&'static str>,
    // Fields that require admin role
    admin_mutable: Vec<&'static str>,
}

impl FieldPolicy {
    fn new() -> Self {
        FieldPolicy {
            user_mutable: vec!["email", "display_name"],
            admin_mutable: vec!["role", "is_verified", "credit_balance"],
        }
    }

    fn is_user_mutable(&self, field: &str) -> bool {
        self.user_mutable.contains(&field)
    }

    fn is_admin_mutable(&self, field: &str) -> bool {
        self.admin_mutable.contains(&field)
    }

    fn is_any_mutable(&self, field: &str) -> bool {
        self.is_user_mutable(field) || self.is_admin_mutable(field)
    }
}

/// Applies a batch of field updates to a user record.
/// This function checks each field against the policy before applying.
async fn apply_field_updates(
    user: &mut StoredUser,
    updates: &HashMap<String, String>,
    caller_role: &str,
    policy: &FieldPolicy,
) -> Result<Vec<String>, Status> {
    let mut applied_fields = Vec::new();

    for (field_name, value) in updates.iter() {
        let authorized = match caller_role {
            "admin" | "superadmin" => {
                policy.is_user_mutable(field_name) || policy.is_admin_mutable(field_name)
            }
            _ => policy.is_user_mutable(field_name),
        };

        if !authorized {
            continue; // silently skip unauthorized fields
        }

        apply_single_field(user, field_name, value, caller_role, policy)?;
        applied_fields.push(field_name.clone());
    }

    Ok(applied_fields)
}

/// Applies a single field update to the user struct.
/// Double-checks authorization at the setter level as defense-in-depth.
fn apply_single_field(
    user: &mut StoredUser,
    field_name: &str,
    value: &str,
    caller_role: &str,
    policy: &FieldPolicy,
) -> Result<(), Status> {
    // Defense-in-depth: re-verify authorization at the setter level
    let allowed = match caller_role {
        "admin" | "superadmin" => policy.is_any_mutable(field_name),
        _ => policy.is_user_mutable(field_name),
    };
    if !allowed {
        return Err(Status::permission_denied(format!(
            "Field '{}' is not mutable for role '{}'",
            field_name, caller_role
        )));
    }

    match field_name {
        "email" => user.email = value.to_string(),
        "display_name" => user.display_name = value.to_string(),
        "role" => user.role = value.to_string(),
        "is_verified" => {
            user.is_verified = value.parse::<bool>().map_err(|_| {
                Status::invalid_argument("is_verified must be true/false")
            })?;
        }
        "credit_balance" => {
            user.credit_balance = value.parse::<i64>().map_err(|_| {
                Status::invalid_argument("credit_balance must be integer")
            })?;
        }
        _ => {
            return Err(Status::invalid_argument(format!(
                "Unknown or immutable field: '{}'",
                field_name
            )));
        }
    }
    Ok(())
}

/// Merges the protobuf update request into a field map.
/// The protobuf `UpdateProfileRequest` has a `field_mask` and `fields` map.
fn extract_update_fields(req: &UpdateProfileRequest) -> HashMap<String, String> {
    let mut result = HashMap::new();

    // If field_mask is provided, only include those fields from the fields map
    if !req.field_mask.is_empty() {
        for mask_field in &req.field_mask {
            if let Some(val) = req.fields.get(mask_field) {
                result.insert(mask_field.clone(), val.clone());
            }
        }
    } else {
        // No field mask means ALL provided fields are included
        result = req.fields.clone();
    }

    result
}

#[tonic::async_trait]
impl UserManagement for UserService {
    async fn update_profile(
        &self,
        request: Request<UpdateProfileRequest>,
    ) -> Result<Response<UpdateProfileResponse>, Status> {
        let metadata = request.metadata();
        let caller_role = metadata
            .get("x-user-role")
            .and_then(|v| v.to_str().ok())
            .unwrap_or("user");
        let caller_id = metadata
            .get("x-user-id")
            .and_then(|v| v.to_str().ok())
            .unwrap_or("")
            .to_string();

        let req_inner = request.into_inner();
        let target_user_id = req_inner.user_id.clone();

        // Authorization: users can only update their own profile
        if caller_role == "user" && caller_id != target_user_id {
            return Err(Status::permission_denied("Cannot update other users"));
        }

        let updates = extract_update_fields(&req_inner);
        let policy = FieldPolicy::new();

        let mut db = self.db.write().await;
        let user = db
            .entry(target_user_id.clone())
            .or_insert_with(|| StoredUser::default_user(&target_user_id));

        let applied = apply_field_updates(user, &updates, caller_role, &policy).await?;

        Ok(Response::new(UpdateProfileResponse {
            success: true,
            updated_fields: applied,
            message: format!("Profile updated for user {}", target_user_id),
        }))
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let service = UserService {
        db: Arc::new(RwLock::new(HashMap::new())),
    };

    Server::builder()
        .add_service(UserManagementServer::new(service))
        .serve("[::1]:50051".parse()?)
        .await?;

    Ok(())
}
